def obtener_stimulusType(targetChar,stimulusCode):
  """
   Esta funcion obtiene el stimulus type a partir de los caracteres objetivo y el codigo de estimulo
  """
  posiciones = {}
  row= 7
  col=0
  for fila in MATRIZ:
      for valor in fila:
          col+=1
          posiciones[valor] = (col, row)
      col=0
      row+=1
  print()
  stimulusType = []
  for i,caracter in enumerate(targetChar[0]):
    col,row = posiciones.get(caracter)
    mascara = (stimulusCode[i] == col) | (stimulusCode[i] == row)
    binarios = mascara.astype(int)
    stimulusType.append(binarios)
  return np.array(stimulusType)

