"""# Procesado de Datos

Parte importante de este trabajo es el procesado de datos, al  utilizar señales encefalograficas, no podemos ingresar  la señal en crudo, porque a nuestro modelo se le compolicaria la clasfiicacion.

## Preprocesado de datos
"""

import numpy as np
from scipy.signal import butter, filtfilt, iirnotch

def preprocess_eeg(signal, fs=240, target_fs=120,
                   lowcut=0.1, highcut=20,
                   notch_freq=50, notch_Q=30,
                   selected_channels=None):
    """
    Preprocesa EEG con:
    - Notch filter
    - Bandpass 0.1–20Hz
    - Downsampling 240→120 Hz
    - Z-score por canal
    - Selección de canales
    """


    # 1. filtro Notch 60hz de red electrica (USA), no necesario porque de todas
    # maneras se tomo la decision de aplicar paso banda  entre 0.1-20hz
    # if notch_freq is not None:
    #     w0 = notch_freq / (fs / 2)
    #     b, a = iirnotch(w0, notch_Q)
    #     signal = filtfilt(b, a, signal, axis=1)

    # 2. Filtro paso banda FIR/IIR
    nyq = fs / 2
    b, a = butter(4, [lowcut/nyq, highcut/nyq], btype='band')
    signal = filtfilt(b, a, signal, axis=1)

    # 3. Cambio de frecuencia de muestreo (240→120 Hz)
    factor = fs // target_fs
    signal = signal[:, ::factor]

    # 4. Normalizacion de Z-score por canal
    mean = np.mean(signal, axis=1, keepdims=True)
    std = np.std(signal, axis=1, keepdims=True)
    signal = (signal - mean) / std

    # 5. Selección de canales
    if selected_channels is not None:
        signal = signal[:,:,selected_channels]

    return signal

"""Tambien es importante samplear nuestras muestras discretas como lo son las señales de los flashes, stimulusCode y stmiulus type para que estos se alineeen al resampleeo y tengan las mismas meiddas entre ellos"""

def sample_diferent_frecuency(array, fs, target_fs):
    """
    Downsampliar el array discreto
    """
    factor = fs // target_fs
    return array[:, ::factor] ## tomando cada 2 muestras

"""Con estas funciones podremos aplicar el procesamienot a la señal y resamplear todos nustros datos"""

