"""## Funcion que nos ayuda a separar en Ventanas


Para entrenar los modelos, las señales EEG se segmentan en
ventanas alineadas al inicio de cada estimulo visual.
Cada ventana representa una posible respuesta P300.

"""

def get_windows(signal, flashing, stimulusCode, stimulusType, window_lenght = .5, SR=120):
  """
  Esta funcion retorna ventanas dado un tamaño determinado de tiempo a tomar de cada caracter desde que sucede un flash

  """
  signal_windows=[]
  flashing_windows = []
  sc_windows=[]
  st_windows=[]
  tam_dataset = len(signal[:,0])
  print("Tam dataset",tam_dataset)
  for character in range (tam_dataset):
    windows_signals = []
    windows_flashing = []
    windows_stimulusCode = []
    windows_stimulusType = []
    window_samples = int(window_lenght * SR) # cuantas muestras tomar de la ventan (SEGUNDOS * SR )
    contador = 0
    anterior = 0
    tam_muestra = len(signal[character])
    for i in range(tam_muestra):
        if flashing[character][i] == 1 and anterior == 0:
            contador += 1
            if i + window_samples < len(flashing[character]):
                windows_signals.append(signal[character, i:i + window_samples])
                windows_flashing.append(flashing[character, i])
                windows_stimulusCode.append(stimulusCode[character, i])
                windows_stimulusType.append(stimulusType[character, i])
        anterior = flashing[character][i]

    signal_windows.append(windows_signals)
    flashing_windows.append(windows_flashing)
    sc_windows.append(windows_stimulusCode)
    st_windows.append(windows_stimulusType)
  return np.array(signal_windows), np.array(flashing_windows), np.array(sc_windows),np.array(st_windows)

SR=120
