from torch.utils.data.dataset import Dataset
from torch.utils.data.dataloader import DataLoader

"""## Funciones para entrenamiento y Validacion
Las siguientes funciones nos ayudaran al entrenamiento y validacion.
El entrenamiento se realiza utilizando el optimizador Adam y la función
de pérdida Cross Entropy. El desempeño se evalúa mediante matrices de
confusión y la metrica de exactitud*** en la tarea de clasificación.

"""

def plot_evolution_training(training_loss,validation_loss): ## mostrar evolucion de perdida de entrenamiento y validacion
  plt.plot(training_loss,color="red",label="Train loss")
  plt.plot(validation_loss,color="blue",label="Validation loss")
  plt.legend()
  plt.show()

def train_loop(model, train_loader, val_loader, optimizer, loss_fn, device="cuda", epochs=10):

    model.to(device)
    training_loss_evolution=[]
    validation_loss_evolution=[]
    for epoch in range(epochs):
        model.train()
        total_loss = 0

        for X_batch, y_batch, sc, ch in train_loader:
            X_batch = X_batch.to(device)
            y_batch = y_batch.to(device)

            optimizer.zero_grad()
            preds = model(X_batch)
            loss = loss_fn(preds, y_batch)
            loss.backward()
            optimizer.step()
            total_loss += loss.item()
        avg_train = total_loss / len(train_loader)
        avg_val = val_loop(model,val_loader,loss_fn,device)
        validation_loss_evolution.append(avg_val)
        training_loss_evolution.append(avg_train)
        print(f"Epoch {epoch+1}/{epochs} Train Loss: {avg_train:.4f} Val Loss: {avg_val:.4f}  ")
    plot_evolution_training(training_loss_evolution,validation_loss_evolution)
    return model

def val_loop(model,val_loader,loss_fn,device):
    model.eval()
    val_loss = 0
    with torch.no_grad():
        for X_batch, y_batch, sc, ch in val_loader:
            X_batch = X_batch.to(device)
            y_batch = y_batch.to(device)

            preds = model(X_batch)
            loss = loss_fn(preds, y_batch)
            val_loss += loss.item()
    avg_val = val_loss / len(val_loader)
    return avg_val

"""## Dataset

En este bloque se define el *dataset* que se utilizará para entrenar la red neuronal.  
El dataset está compuesto por los siguientes atributos:

- **X**: señal EEG segmentada en ventanas de tamaño `tamaño_ventana × numero_canales` .
- **Y**: etiqueta binaria que indica si  **P300** está presente `1` o no `0`.
- **stimulusCode**: código del estímulo presentado en el momento del *flash*.
- **char**: carácter asociado al estímulo.

La clase `DatasetCNN` implementa la función `__getitem__`, la cual recibe un índice global y se encarga de localizar el **carácter** y la **época** correspondiente dentro del dataset.  
Esto permite mantener un control adecuado de los datos y evitar que se mezclen épocas o caracteres durante el entrenamiento.
"""

class DatasetCNN(Dataset):
    def __init__(self, X, Y,stimulusCode,char):
        self.X = torch.tensor(X, dtype=torch.float32)
        self.Y = torch.tensor(Y, dtype=torch.long)
        self.stimulusCode = stimulusCode
        self.char=char
        self.N_char, self.N_epochs = self.Y.shape # Cuantos caracteres tenemos y las epocas

    def __len__(self):
        return self.N_char * self.N_epochs
    def get_char(self):
        return self.char
    def __getitem__(self, idx):
        c = idx // self.N_epochs   # carácter
        e = idx %  self.N_epochs   # epoch

        x = self.X[c, e]           # [window_length,Nc]
        y = self.Y[c, e]           # 0/1
        x = x.permute(1,0)         # [Nc,window_length]
        return x, y

"""### **Subset Dataset auxiliar**

Este dataset auxiliar se utiliza para facilitar la división en conjuntos de entrenamiento y validación, asegurando que los caracteres no se mezclen entre conjuntos.

Para ello, se pasa el dataset original junto con una lista de índices de caracteres (char_indices).
De esta forma, todas las épocas correspondientes a un mismo carácter permanecen juntas durante el entrenamiento o la validación.
"""

class CharSubset(Dataset):
    def __init__(self, dataset, char_indices):
        self.dataset = dataset
        self.char_indices = char_indices
        self.N_epochs = dataset.N_epochs

    def __len__(self):
        return len(self.char_indices) * self.N_epochs

    def __getitem__(self, idx):
        c = idx // self.N_epochs
        e = idx %  self.N_epochs

        real_c = self.char_indices[c]

        x = self.dataset.X[real_c, e].permute(1, 0)
        y = self.dataset.Y[real_c, e]
        sc = self.dataset.stimulusCode[real_c, e]
        ch = self.dataset.char[real_c]
        return x,y,sc,ch

"""# EXPERIMENTACION

- En primer lugar, se implementa una red neuronal convolucional diseñada para aprender patrones espaciales y temporales presentes en las señales EEG.

- Despues, se implementa una EEGNet es una arquitectura de red neuronal específicamente diseñada para señales EEG, capaz de aprender filtros temporales y espaciales de manera eficiente incluso con un número reducido de parámetros.

## Módulo CNN

El objetivo de este modelo **no es predecir directamente el carácter** pensado por el sujeto, sino **detectar la presencia del potencial P300** en ventanas individuales de la señal EEG.

La decodificación del carácter se realiza posteriormente, utilizando las predicciones de P300 asociadas a los estímulos de **filas y columnas**.

La arquitectura propuesta consiste en:
- Una **convolución espacial**, que combina la información de los canales EEG.
- Una **convolución temporal**, que extrae patrones relevantes a lo largo del tiempo.
- Capas totalmente conectadas para la clasificación binaria (*P300 / No P300*).
"""

class CNNeeg(nn.Module):
    def __init__(self, Nelec=64, Nt=78, Ns=10):
        super().__init__()

        # L1 - Spatial convolution
        self.conv_spatial = nn.Conv2d(
            in_channels=1,
            out_channels=Ns,
            kernel_size=(Nelec, 1),  # colapsa canales
            stride=1,
            padding=0
        )

        # L2 - Temporal convolution
        self.conv_temporal = nn.Conv2d(
            in_channels=Ns,
            out_channels=5 * Ns,
            kernel_size=(1, 13),  # reduce tiempo de 78 a 66
            stride=1,
            padding=0
        )

        # Auto-calcular el tamaño para FC
        with torch.no_grad():
            dummy = torch.zeros(1, 1, Nelec, Nt)
            o = torch.tanh(self.conv_spatial(dummy))
            o = torch.tanh(self.conv_temporal(o))
            flat = o.reshape(1, -1).shape[1]

        self.fc1 = nn.Linear(flat, 100)
        self.fc2 = nn.Linear(100, 2)

    def forward(self, x):
      # x = [batch, 64, 78]
        x = x.unsqueeze(1)  # -> [batch,1,64,78]

        x = torch.tanh(self.conv_spatial(x))
        x = torch.tanh(self.conv_temporal(x))

        x = x.reshape(x.size(0), -1)

        x = torch.sigmoid(self.fc1(x))
        x = self.fc2(x)

        return x

