"""### Funciones de Test
Desarrollamos las funciones de test y funciones auxiliares como obtener un reporte y visualizar los resultados de la clasificacion
"""

def test_p300(model, loader, device):
    model.eval()
    preds, probs, labels = [], [], []
    codes, chars = [], []

    with torch.no_grad():
        for X, y, sc, ch in loader:
            X = X.to(device)

            out = model(X)                     # logits
            prob = torch.softmax(out, dim=1)[:, 1]
            pred = torch.argmax(out, dim=1)

            preds.append(pred.cpu())
            probs.append(prob.cpu())
            labels.append(y.cpu())
            codes.append(sc)
            chars.append(ch)

    return {
        "pred": torch.cat(preds),        # 0 / 1
        "prob": torch.cat(probs),        # P(P300)
        "y": torch.cat(labels),
        "stimulusCode": torch.cat(codes),
        "char": np.concatenate(chars),
    }

from sklearn.metrics import confusion_matrix, accuracy_score, precision_score, recall_score, f1_score

def show_report(all_labels,all_predictions):
  cm = confusion_matrix(all_labels, all_predictions)
  print("Confusion Matrix:\n", cm)

  TP = cm[1, 1]
  TN = cm[0, 0]
  FP = cm[0, 1]
  FN = cm[1, 0]

  print(f"True Positives (TP): {TP}")
  print(f"True Negatives (TN): {TN}")
  print(f"False Positives (FP): {FP}")
  print(f"False Negatives (FN): {FN}")

  accuracy = accuracy_score(all_labels, all_predictions)
  precision = precision_score(all_labels, all_predictions)
  recall = recall_score(all_labels, all_predictions)
  f1 = f1_score(all_labels, all_predictions)

  print(f"Accuracy: {accuracy:.4f}")
  print(f"Precision: {precision:.4f}")
  print(f"Recall: {recall:.4f}")
  print(f"F1-Score: {f1:.4f}")

"""### **Decodificación**

Cada caracter de la tabla P300 Speller se compone de varios flashes que lo representan, correspondientes a filas y columnas de la misma tabla.
Por lo tanto, las predicciones del modelo (P300 ó No P300) se agrupan
por carácter para despues poder codificar al caracter que representan.
"""

def agrupar_por_caracter(preds, probs, codes, chars, n_per_char):
    grupos = []

    for i in range(0, len(preds), n_per_char):
        grupos.append({
            "pred": preds[i:i+n_per_char].numpy(),
            "prob": probs[i:i+n_per_char].numpy(),
            "code": codes[i:i+n_per_char].numpy(),
            "char_real": chars[i]
        })

    return grupos

"""### **Inferencia de Fila y Columna**

Para cada carácter, se identifican los estímulos clasificados como P300.
La fila y la columna con mayor frecuencia de respuestas P300 se consideran
como las que estaba observando el usuario.
"""

def inferir_fila_columna(grupo):
    score_filas = {i: 0.0 for i in range(7, 13)}
    score_columnas = {i: 0.0 for i in range(1, 7)}

    for code, p in zip(grupo["code"], grupo["prob"]):
        if 1 <= code <= 6:
            score_columnas[code] += p
        elif 7 <= code <= 12:
            score_filas[code] += p

    fila = max(score_filas, key=score_filas.get)
    columna = max(score_columnas, key=score_columnas.get)
    return fila, columna

"""A partir de la fila y columna inferidas, se obtiene el carácter
correspondiente dentro de la matriz del teclado P300.
"""

from sklearn.metrics import confusion_matrix, accuracy_score
def decodificar_caracter(fila, columna):
    f = fila - 7
    c = columna - 1
    return MATRIZ[f][c]
def decodificar_speller(grupos):
    chars_pred = []
    chars_real = []

    for g in grupos:
        fila, columna = inferir_fila_columna(g)
        char_pred = decodificar_caracter(fila, columna)

        chars_pred.append(char_pred)
        chars_real.append(g["char_real"])

    return chars_real, chars_pred

"""#### Visualización de la Matriz de Confusión de Caracteres

Para una mejor comprensión de las predicciones a nivel de carácter, se muestra la matriz de confusión utilizando un mapa de calor (`heatmap`). En este gráfico, cada celda `(i, j)` representa el número de veces que el carácter real `i` fue clasificado como el carácter `j`.
"""

import matplotlib.pyplot as plt
import seaborn as sns
from sklearn.metrics import confusion_matrix

def plot_character_confusion_matrix(real_chars, predicted_chars):
    print("Codigos Reales")
    print([str(char) for char in real_chars])
    print("Codigos Predichos")
    print(predicted_chars)
    # Obtener todos los caracteres únicos presentes en las etiquetas reales y predichas
    all_chars = sorted(list(set(real_chars + predicted_chars)))

    # Calcular la matriz de confusión
    cm = confusion_matrix(real_chars, predicted_chars, labels=all_chars)
    accuracy = accuracy_score(real_chars, predicted_chars)
    print("ACCURACY LETRAS",accuracy)
    # Crear el mapa de calor
    plt.figure(figsize=(12, 10))
    sns.heatmap(cm, annot=True, fmt='d', cmap='Blues', xticklabels=all_chars, yticklabels=all_chars)
    plt.xlabel('Caracter Predicho')
    plt.ylabel('Caracter Real')
    plt.title('Matriz de Confusión de Caracteres')
    plt.show()

"""### **Testeo y Resultados**"""

def test_and_show_report(model,test_loader,device="cuda"):
  ventanas_por_caracter = test_loader.dataset.dataset.X.shape[1]
  out = test_p300(model, test_loader, DEVICE)
  grupos = agrupar_por_caracter(out["pred"],out["prob"],out["stimulusCode"],out["char"],n_per_char=ventanas_por_caracter)
  chars_real, chars_pred = decodificar_speller(grupos)
  show_report(out["y"],out["pred"])
  plot_character_confusion_matrix(chars_real, chars_pred)

